"""Android entry point generated by arena_exe_builder."""
import os
import runpy
import sys
import traceback

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
GAME_MODULE = "box_game"

try:
    import arena_android_shim as shim
    shim.install()
    os.chdir(shim.data_dir())
    runpy.run_module(GAME_MODULE, run_name="__main__", alter_sys=True)
except SystemExit:
    raise
except BaseException:
    text = traceback.format_exc()
    print(text)
    try:
        with open(os.path.join(os.getcwd(), "arena_android_crash.log"), "w", encoding="utf-8") as handle:
            handle.write(text)
    except Exception:
        pass
    raise
